(function () {
  "use strict";

  function _waEmbed(config) {
    if (!config || !config.whatsAppNumber) {
      console.error("WhatsApp Widget: whatsAppNumber is required");
      return;
    }

    // Create widget container
    const container = document.createElement("div");
    container.id = "wa-widget-container";

    // Position styling
    const position = config.btnPosition === "left" ? "left" : "right";
    const leftMargin =
      position === "left" ? (config.marginLeft || 20) + "px" : "auto";
    const rightMargin =
      position === "right" ? (config.marginRight || 20) + "px" : "auto";

    // Apply styles
    Object.assign(container.style, {
      position: "fixed",
      bottom: (config.marginBottom || 20) + "px",
      left: leftMargin,
      right: rightMargin,
      zIndex: config.zIndex || 999999,
      display: "flex",
      flexDirection: "column",
      alignItems: position === "left" ? "flex-start" : "flex-end",
      gap: "10px",
    });

    // Create button
    const button = document.createElement("button");
    button.id = "wa-widget-button";
    button.setAttribute("aria-label", "WhatsApp Chat");

    const buttonColor = config.btnColor || "#16BE45";
    const textColor = config.btnColorScheme === "dark" ? "#000000" : "#FFFFFF";
    const cornerRadius = config.cornerRadius || 40;

    Object.assign(button.style, {
      backgroundColor: buttonColor,
      color: textColor,
      border: "none",
      borderRadius: cornerRadius + "px",
      padding: "12px 20px",
      fontSize: "16px",
      fontWeight: "600",
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      gap: "8px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
      transition: "all 0.3s ease",
      fontFamily:
        '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    });

    // WhatsApp SVG icon
    const icon = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    icon.setAttribute("width", "20");
    icon.setAttribute("height", "20");
    icon.setAttribute("viewBox", "0 0 24 24");
    icon.setAttribute("fill", "currentColor");
    icon.innerHTML = `
      <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/>
    `;

    const text = document.createElement("span");
    text.textContent = config.ctaText || "WhatsApp Us";

    button.appendChild(icon);
    button.appendChild(text);

    // Hover effect
    button.addEventListener("mouseenter", () => {
      button.style.transform = "scale(1.05)";
      button.style.boxShadow = "0 6px 16px rgba(0,0,0,0.2)";
    });

    button.addEventListener("mouseleave", () => {
      button.style.transform = "scale(1)";
      button.style.boxShadow = "0 4px 12px rgba(0,0,0,0.15)";
    });

    // Click handler - open WhatsApp
    button.addEventListener("click", () => {
      const phone = config.whatsAppNumber;
      const message = encodeURIComponent(config.welcomeMessage || "Hello");
      const url = `https://wa.me/${phone}?text=${message}`;
      window.open(url, "_blank");
    });

    container.appendChild(button);
    document.body.appendChild(container);
  }

  // Expose function globally
  window._waEmbed = _waEmbed;
})();
